/* ---------- หน้าจอ ---------- */
const mwCard=m=>`<button class="rd-fc press" data-go="mwdet" data-c="${m.zh}"><span class="zh">${m.zh}</span><span class="py">${pyHtml(m.py)}</span><span class="th">${m.th}</span><span class="meta"><small>${m.n}</small></span></button>`;
const mwDock=()=>`<div class="dock"><button class="pill press" data-go="mwprac"><b>ฝึกรวมทุกแบบ</b><small>6 ข้อ แล้วปิดท้ายด้วยรอบบอส</small></button><button class="pill sm ghost press mv-dock2" data-go="mwsort">เกมแยกใส่ตะกร้า · 60 วินาที</button></div>`;
SC.mwroom=(p)=>{const lv=p&&p.lv!=null?(+p.lv||0):Math.min(5,Math.max(1,curLv())),lvs=[1,2,3,4,5];
 const body=`<div class="rd-mn"><div class="rm">${M('think')}</div><div class="rd-bub"><b>หลักการใช้</b><div style="margin-top:2px">ตัวเลข + ลักษณนาม + คำนาม</div><div style="margin-top:4px"><span class="zh" style="font-size:20px">${zhHtml('一本书','yì běn shū')}</span> = หนังสือ 1 เล่ม</div></div></div>
 <div class="rd-sech"><b>ลักษณนามที่ใช้บ่อย · ${MW.length} คำ</b><small>แตะเพื่อดูตัวอย่าง</small></div>
 <div class="rd-lvf" role="group" aria-label="กรองตามระดับ"><button class="${!lv?'on':''}" data-go="mwlv" data-lv="0">ทุกระดับ</button>${lvs.map(n=>`<button class="${lv===n?'on':''}" data-go="mwlv" data-lv="${n}">ระดับ ${n}</button>`).join('')}</div>
 ${lvs.filter(n=>!lv||n===lv).map(n=>`<div class="rd-sech"><b>ระดับ ${n}</b><small>${MW.filter(m=>m.lv===n).length} คำ</small></div><div class="rd-fgrid">${MW.filter(m=>m.lv===n).map(mwCard).join('')}</div>`).join('')}<div style="height:180px"></div>`;
 return {title:'ลักษณนาม',backLabel:'แหล่งความรู้',noRefresh:true,body,extra:mwDock()}};
/* หน้ารายละเอียด: ภาพทั้งกลุ่มก่อน แล้วจุดสังเกต ระวังสับสน ตัวอย่างประโยค */
SC.mwdet=(p)=>{const m=MWI[p&&p.c]||MW[0],c=m.zh,X=MVX[c];const sp=t=>`<button class="rd-spk sm press" data-act="audio" data-t="${t}" aria-label="ฟัง ${t}">${SPK}</button>`;
 let fam=mvOf(c).slice(0,6).map(n=>({a:n.a,ph:n.ph,th:n.pth}));
 if(fam.length<6)m.ex.forEach(e=>{if(fam.length<6&&!fam.some(f=>f.ph===e.zh)&&(!e.a||!fam.some(f=>f.a===e.a)))fam.push({a:e.a||'',ph:e.zh.replace(/。$/,''),th:e.th})});
 const conf=[...X.c].map(z=>mvOf(z)[0]).filter(Boolean).slice(0,3);
 const gq=MV_GRP[c]&&MV_GRP[c].nw;
 const body=`<div class="rd-fh card mv-fh"><div class="rd-ftile"><span class="zh">${c}</span></div><div class="rd-fht"><div class="rd-kick2">ลักษณนาม · ระดับ ${m.lv}</div><div class="rd-fth">${m.th}</div><div class="rd-fpy">อ่านว่า <b>${pyHtml(m.py)}</b></div></div></div>
 <div class="rd-sech"><b>ทุกอย่างนี้ใช้ ${c}</b><small>แตะภาพเพื่อฟัง</small></div>
 <div class="mv-g3">${fam.map(f=>`<button class="mv-pc press" data-act="audio" data-t="${f.ph}" aria-label="ฟัง ${f.ph} ${f.th}">${(f.a&&mvA(f.a))||`<span class="mv-nopic"><small>${f.th}</small></span>`}<span class="l zh">${f.ph}</span></button>`).join('')}</div>
 <div class="mv-why">${mvSvg(X.sh)}<div><b>ดูที่${X.k}: ${X.t}</b><span>${X.y}</span></div></div>
 ${conf.length?`<div class="rd-sech"><b>ระวังสับสน</b></div>${conf.map(n=>`<div class="mv-mx">${mvA(n.a)}<div class="t"><span class="zh">${n.ph}</span><br>${mvRs(n)}</div>${sp(n.ph)}</div>`).join('')}`:''}
 <div class="rd-sech"><b>ตัวอย่างประโยค</b><small>${m.ex.length} ประโยค</small></div>
 ${m.ex.map(e=>`<div class="rd-pic card">${e.a?art('word',e.a,'',''):''}<div class="t" style="flex:1"><b style="font-size:22px"><span class="zh" style="color:inherit">${zhHtml(e.zh,e.py)}</span></b><div style="font-size:14.5px;margin-top:2px">${pyHtml(e.py)}</div><small style="margin-top:2px">${e.th}</small></div>${sp(e.zh)}</div>`).join('')}
 ${m.cau?`<div class="rd-weak"><b>ข้อควรระวัง</b><p>${m.cau}</p></div>`:''}<div style="height:120px"></div>`;
 return {title:c,backLabel:'ลักษณนาม',noRefresh:true,right:`<button class="rd-spk press" data-act="audio" data-t="${m.ex[0].zh}" aria-label="ฟังตัวอย่าง">${SPK}</button>`,body,
  extra:`<div class="dock"><button class="pill press" data-go="mwprac" data-c="${c}"><b>${gq?`ฝึก ${c} แบบทายกลุ่ม`:`ฝึกลักษณนาม ${c}`}</b><small>6 ข้อ · ใช้เวลาราว 2 นาที</small></button></div>`}};
SC.mwprac=(p)=>({nav:sessNav,body:'<div class="stage" id="stage"></div>',extra:sessExtra,noRefresh:true,unmount(){stopAudio()},
 mount(el){const c=p&&MWI[p.c]?p.c:'';const {steps,boss}=mvBuild(c);
  session(el,steps,res=>{const tot=res.log.length,ok=res.correct,xp=evX(ok*8),coins=evC(ok*2);addXp(xp,null,true);addCoins(coins,true);
   const stats=[['ตอบถูก',ok+'/'+tot]];if(!c)stats.push(['รอบบอส',boss.win?'ชนะบอส':'บอสเหลือพลัง '+boss.hp+'%']);
   replace('result',{title:c?'ฝึกลักษณนาม '+c+' เสร็จแล้ว':(boss.win?'ชนะบอสแล้ว':'จบรอบฝึกแล้ว'),mascot:(!c&&boss.win)?'celebrate':(ok>=tot*.6?'correct':'wrong'),sub:`ตอบถูก ${ok}/${tot}`,xp,coins,stats})})}});
/* ---------- เกมแยกใส่ตะกร้า (60 วินาที) ---------- */
const MV_SORT_T=60,MV_SORT_UNLOCK=20;
/* ตะกร้าเกมแยก: ใช้ลักษณนามระดับไม่เกินผู้เรียน (ไม่ใช้ 个) ที่มีภาพอย่างน้อย 3 ภาพ ถ้าไม่พอขยับขึ้นทีละระดับ · ระดับ 3 ขึ้นไปได้ชุดเดิม 条 张 只 本 */
function mvSortB(four){const k=four?4:3,pref=['条','张','只','本'];
 for(let n=Math.max(1,curLv());n<=5;n++){const c=MW.filter(m=>m.lv<=n&&m.zh!=='个'&&MVN.filter(x=>x.m===m.zh&&mvA(x.a)).length>=3).map(m=>m.zh)
   .sort((a,b)=>(pref.includes(b)-pref.includes(a))||(MVN.filter(x=>x.m===b&&mvA(x.a)).length-MVN.filter(x=>x.m===a&&mvA(x.a)).length));
  if(c.length>=k)return c.slice(0,k)}
 return pref.slice(0,k)}
const MV_CLK=`<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.5 2M9 2h6"/></svg>`;
SC.mwsort=()=>{let tick=null,live=false;return {nav:`<div class="seshnav"><button class="x" data-ms="quit" aria-label="ปิด">×</button><div class="mv-navt">แยกใส่ตะกร้า</div><span style="width:32px"></span></div>`,
 body:'<div class="stage mv" id="mvs"></div>',extra:'<div class="dock" id="mvsd" hidden></div>',noRefresh:true,
 unmount(){clearInterval(tick);live=false;stopAudio()},
 mount(el){const st=$('#mvs',el),dk=$('#mvsd',el);let G;
  function start(){clearInterval(tick);const four=(S.mwSortOk||0)>=MV_SORT_UNLOCK,B=mvSortB(four);
   G={B,end:Date.now()+MV_SORT_T*1000,score:0,combo:0,best:0,n:0,ok:0,miss:[],pool:[],cur:null,lock:false,four,in:Object.fromEntries(B.map(z=>[z,[]]))};
   dk.hidden=true;dk.innerHTML='';live=true;
   st.innerHTML=`<div class="mv-hud"><div class="mv-time">${MV_CLK} <span id="mvt">1:00</span></div><div class="mv-combo" id="mvc" hidden></div><div class="mv-score" id="mvsc" aria-label="คะแนน">0</div></div>
    <div class="mv-tbar"><i id="mvtb" style="width:100%"></i></div>
    <div class="mv-fall"><div class="mv-item" id="mvi"></div><div class="mv-plus" id="mvp" aria-live="polite"></div></div>
    <div class="mv-cap" style="margin:0 20px 10px">แตะตะกร้าที่ใช้ลักษณนามถูกต้อง</div>
    <div class="mv-bk${four?' four':''}">${B.map(z=>`<button class="mv-b press" data-b="${z}" aria-label="ตะกร้า ${z} ${MVX[z].g}"><span class="zh">${z}</span><span class="t">${MVX[z].g}</span><span class="in"></span></button>`).join('')}</div><div style="height:40px"></div>`;
   nextItem();tick=setInterval(upd,200);upd()}
  function nextItem(){if(!G.pool.length){G.pool=shuffle(MVN.filter(n=>G.B.includes(n.m)&&mvA(n.a)));if(G.cur&&G.pool[G.pool.length-1]===G.cur)G.pool.unshift(G.pool.pop())}
   G.cur=G.pool.pop();const n=G.cur,it=$('#mvi',st);it.classList.remove('in','hint');void it.offsetWidth;
   it.innerHTML=`${mvA(n.a)}<div class="zh">${n.d}</div><div class="s">${MVN_PY(n)} · ${n.th}</div><div class="h" aria-live="polite"></div>`;it.classList.add('in');G.lock=false}
  function upd(){if(!live)return;const left=Math.max(0,G.end-Date.now()),s=Math.ceil(left/1000);const t=$('#mvt',st),b=$('#mvtb',st);if(t)t.textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if(b)b.style.width=(left/(MV_SORT_T*10))+'%';if(left<=0)finish()}
  function hud(){$('#mvsc',st).textContent=G.score;const c=$('#mvc',st);c.hidden=G.combo<2;c.textContent='ต่อเนื่อง ×'+G.combo}
  function tap(z,btn){if(!live||G.lock||!G.cur)return;G.lock=true;const n=G.cur;G.n++;const ok=n.m===z,p=$('#mvp',st);
   if(ok){G.ok++;G.combo++;G.best=Math.max(G.best,G.combo);const pts=10+(G.combo>=3?5:0);G.score+=pts;vib(10);
    btn.classList.remove('hit','bad');void btn.offsetWidth;btn.classList.add('hit');const inn=G.in[z];inn.push(n.a);if(inn.length>3)inn.shift();$('.in',btn).innerHTML=inn.map(mvA).join('');
    p.textContent='+'+pts;p.className='mv-plus on';hud();setTimeout(()=>{if(live)nextItem()},260)}
   else{G.combo=0;vib([30,40,30]);G.miss.push({n,pick:z});btn.classList.remove('hit','bad');void btn.offsetWidth;btn.classList.add('bad');hud();
    const it=$('#mvi',st);it.classList.add('hint');$('.h',it).innerHTML=`${n.ph} · ${mvRs(n)}`;setTimeout(()=>{if(live)nextItem()},1100)}}
  function finish(){if(!live)return;live=false;clearInterval(tick);const was=S.mwSortOk||0;S.mwSortOk=was+G.ok;S.mwSortBest=Math.max(S.mwSortBest||0,G.score);
   const xp=evX(G.ok*2),coins=evC(Math.floor(G.ok/2));if(xp)addXp(xp,null,true);if(coins)addCoins(coins,true);save();
   const seen=new Set(),mx=G.miss.filter(x=>!seen.has(x.n.a)&&seen.add(x.n.a)).slice(0,4);
   const cnt={};G.miss.forEach(x=>cnt[x.n.m]=(cnt[x.n.m]||0)+1);const rv=Object.keys(cnt).sort((a,b)=>cnt[b]-cnt[a])[0]||'';
   const unl=!G.four&&S.mwSortOk>=MV_SORT_UNLOCK,nb=mvSortB(true).find(z=>!G.B.includes(z))||'本';
   st.innerHTML=`<div class="mv-resm">${M('cheer')}</div><div class="mv-h" style="margin-top:0">หมดเวลา</div>
    <div class="card mv-res"><div class="mv-stat"><div><b>${G.n}</b><span>แยกแล้ว</span></div><div><b>${G.ok}</b><span>ถูกต้อง</span></div><div><b>×${G.best}</b><span>ต่อเนื่องสูงสุด</span></div><div><b>${G.score}</b><span>คะแนน</span></div></div>
    <div class="mv-rw">+${xp} XP · +${coins} เหรียญ</div></div>
    <div class="mv-sec">ที่ยังสับสน</div>
    ${mx.length?mx.map(x=>`<div class="mv-mx">${mvA(x.n.a)}<div class="t"><span class="zh">${x.n.ph}</span> <span class="mv-pk">เลือก ${x.pick}</span><br>${x.n.r} ใช้ ${x.n.m}</div></div>`).join(''):`<div class="mv-mx"><div class="t">รอบนี้ไม่มีคำที่ตอบผิด</div></div>`}
    ${G.four?'':`<div class="mv-sec">รอบถัดไป</div><div class="mv-mx"><span class="zh mv-bz">${nb}</span><div class="t">${unl?`<b>ปลดล็อกตะกร้า ${nb} แล้ว</b><br>รอบถัดไปมีตะกร้า 4 ใบ`:`<b>เพิ่มตะกร้า ${nb}</b><br>เมื่อถูกต้องครบ ${MV_SORT_UNLOCK} ชิ้น ตะกร้าจะเพิ่มเป็น 4 ใบ · ตอนนี้ ${Math.min(S.mwSortOk,MV_SORT_UNLOCK)}/${MV_SORT_UNLOCK}`}</div></div>`}<div style="height:170px"></div>`;
   dk.innerHTML=`<button class="pill press" data-ms="again"><b>เล่นอีกรอบ</b></button>${rv?`<button class="pill sm ghost press mv-dock2" data-ms="rev" data-c="${rv}">ทบทวนคำที่สับสน</button>`:`<button class="pill sm ghost press mv-dock2" data-ms="back">กลับห้องลักษณนาม</button>`}`;dk.hidden=false;
   const sc=$('.scroller',el);if(sc)sc.scrollTop=0;if(G.ok>=10)confetti(60)}
  el.addEventListener('click',e=>{const b=e.target.closest('[data-b]');if(b&&el.contains(b)){tap(b.dataset.b,b);return}const t=e.target.closest('[data-ms]');if(!t||!el.contains(t))return;const a=t.dataset.ms;
   if(a==='quit'){if(live)quitSheet();else pop()}else if(a==='again')start();else if(a==='rev')replace('mwdet',{c:t.dataset.c});else if(a==='back')pop()});
  start()}}};
const MVN_PY=n=>n.php.split(' ').slice(2).join(' ');
Object.assign(window.GOX,{mwroom(){push('mwroom')},mwlv(el){replace('mwroom',{lv:+el.dataset.lv||0})},mwdet(el){push('mwdet',{c:el.dataset.c})},mwprac(el){push('mwprac',{c:el.dataset.c||''})},mwsort(){push('mwsort')}});
